spec.expr:
min(
  up{
    job="traefik",
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

sum by (code) (
  rate(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

100 *
(
  sum(
    rate(
      traefik_entrypoint_requests_total{
        departamento=~"$departamento",
        nodename=~"$nodename",
        code=~"4.."
      }[$__rate_interval]
    )
  )
  or vector(0)
)
/
clamp_min(
  sum(
    rate(
      traefik_entrypoint_requests_total{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum by (code) (
  rate(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

sum by (code) (
  increase(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__range]
  )
)

sum by (entrypoint) (
  traefik_open_connections{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

sum by (entrypoint) (
  rate(
    traefik_entrypoint_request_duration_seconds_sum{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)
/
clamp_min(
  sum by (entrypoint) (
    rate(
      traefik_entrypoint_request_duration_seconds_count{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum by (entrypoint) (
  rate(
    traefik_entrypoint_requests_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

sum by (entrypoint) (
  rate(
    traefik_entrypoint_responses_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

time() -
max(
  traefik_config_last_reload_success{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

sum(
  rate(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)
or vector(0)

max(
  traefik_config_reloads_total{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

increase(
  traefik_config_reloads_total{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }[$__rate_interval]
)

sum by (protocol) (
  traefik_open_connections{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

100 *
(
  sum(
    rate(
      traefik_entrypoint_requests_total{
        departamento=~"$departamento",
        nodename=~"$nodename",
        code=~"5.."
      }[$__rate_interval]
    )
  )
  or vector(0)
)
/
clamp_min(
  sum(
    rate(
      traefik_entrypoint_requests_total{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[$__rate_interval]
    )
  ),
  0.000001
)

(
  sum(
    rate(
      traefik_entrypoint_request_duration_seconds_sum{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[$__rate_interval]
    )
  )
  or vector(0)
)
/
clamp_min(
  sum(
    rate(
      traefik_entrypoint_request_duration_seconds_count{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[$__rate_interval]
    )
  ),
  0.000001
)

sum(
  traefik_entrypoint_requests_total{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

sum(
  rate(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

sum(
  rate(
    traefik_entrypoint_requests_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

sum(
  rate(
    traefik_entrypoint_responses_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)

sum by (entrypoint) (
  rate(
    traefik_entrypoint_requests_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[$__rate_interval]
  )
)
